from taf.nms.nom.schemas.base import SchemaObject, SchemaField, SchemaObjects


class FastPassPackageVersion(SchemaObject):
    version_id = SchemaField(name="version_id", not_null=True)

    def __init__(self, version_id):
        self.version_id = version_id
        super(FastPassPackageVersion, self).__init__()


class FastPassPackage(SchemaObject):
    package_id = SchemaField(name="package_id", not_null=True)
    versions = SchemaField(name="versions", not_null=True, klass=FastPassPackageVersion, many=True)

    def __init__(self, package_id, versions):
        self.package_id = package_id
        self.versions = versions
        super(FastPassPackage, self).__init__()


class FastPassPackages(SchemaObjects):
    schema = FastPassPackage
